// Wrapper-copy CI pin (Plan 2, Task 25; closes Task 24's one unpinned
// propagation link).
//
// The content chain has three copies of the SAME pack documents:
//
//   1. `sancta_via_devotional_engine/test/fixtures/packs/*.json` — the single
//      source of truth;
//   2. this package's `lib/src/embedded_packs.dart`, generated by
//      `tool/embed_packs.dart` (the in-memory repository's catalog);
//   3. `sancta_via_devotionals/assets/content/packs/*.json`, the app's
//      committed copies (pinned by the app's own asset test).
//
// Link 3 was already pinned. Link 2 was not: the Angelus' three-anchor change
// could reach the engine fixtures and the app assets while the wrapper's
// embed stayed on the old single anchor — the app would read the engine
// pack, but tests and demos using `InMemoryProgramRepository` would silently
// ship a stale catalog. This test reads the fixtures from disk and requires
// the embedded JSON to be a byte-for-byte copy of EVERY fixture, with the
// angelus called out explicitly (the pack the T24 three-anchor change
// touched).
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:sancta_via_devotional_engine_riverpod/src/embedded_packs.dart';

/// The engine fixtures this package's embed is generated from, relative to
/// the package root (the `flutter test` working directory).
const String _fixturesDir =
    '../sancta_via_devotional_engine/test/fixtures/packs';

/// The fixture files in sorted filename order — the order `embed_packs.dart`
/// uses.
List<File> _fixtureFiles() {
  final List<File> files = <File>[
    for (final FileSystemEntity entry in Directory(_fixturesDir).listSync())
      if (entry is File && entry.path.endsWith('.json')) entry,
  ]..sort((File a, File b) => a.path.compareTo(b.path));
  return files;
}

/// The pack id a fixture file declares (its filename stem is the id in the
/// engine's fixture set).
String _idOf(File file) =>
    file.uri.pathSegments.last.replaceAll(RegExp(r'\.json$'), '');

void main() {
  test('embeddedPackJson is a byte-for-byte copy of the engine fixtures', () {
    final List<File> fixtures = _fixtureFiles();
    expect(
      fixtures,
      isNotEmpty,
      reason: 'the engine fixture directory must be readable',
    );

    // The generated map keys follow the sorted fixture filename order, so a
    // fixture added/removed/renamed without re-running the embed fails here.
    expect(
      embeddedPackJson.keys.toList(),
      <String>[for (final File file in fixtures) _idOf(file)],
      reason:
          're-run `dart tool/embed_packs.dart` after adding, removing, or '
          'renaming an engine fixture',
    );

    for (final File file in fixtures) {
      final String id = _idOf(file);
      expect(
        embeddedPackJson[id],
        file.readAsStringSync(),
        reason:
            'embedded_packs.dart must be regenerated from the engine '
            'fixtures (single source of truth) — run '
            '`dart tool/embed_packs.dart` in this package',
      );
    }
  });

  test('the embedded Angelus keeps all three Task-24 anchors', () {
    final String angelus = embeddedPackJson['angelus']!;
    // The propagation seam Task 24 changed: a stale embed would still parse
    // and schedule ONE anchor, so pin the authored hours themselves.
    expect(angelus, contains('"hour": 6'));
    expect(angelus, contains('"hour": 12'));
    expect(angelus, contains('"hour": 18'));
    expect(
      embeddedPackJson['angelus'],
      File('$_fixturesDir/angelus.json').readAsStringSync(),
      reason:
          'the app-facing embed must match the engine fixture byte for '
          'byte',
    );
  });
}
